/** Existing recordings are the primary audio path. Missing recordings remain silent.
 * Speech is played only from matched existing recordings; missing lines remain silent. */
import {RecordedAudio} from './recorded-audio.js?v=21';
const bounded=(v,a,b)=>Math.max(a,Math.min(b,v));
export class StreetAudio {
 constructor(soundtrack){this.soundtrack=soundtrack;this.preferences={enabled:true,music:true,beat:false,voice:false,voiceURI:'',volume:.6};this.recorded=new RecordedAudio();this.time=0;this.lastCue=-10;this.paused=false;this.utterance=null;this.pendingVoice=[];this.manifestRequested=false;}
 ready(){const s=this.soundtrack,c=s?.ctx;if(this.paused||!this.preferences.enabled||s?.muted||s?.paused||!c||c.state!=='running')return false;if(this.ctx!==c){this.bus?.disconnect();this.ctx=c;this.bus=c.createGain();this.bus.gain.value=this.preferences.volume;this.bus.connect(s.effects||s.master);this.recorded.attach(c,this.bus,s.music);}if(!this.manifestRequested){this.manifestRequested=true;this.recorded.loadManifest();}return true;}
 cue(id,{distance=0,pan=0}={}){if(distance>24||!this.ready()||this.time-this.lastCue<1)return false;const clip=this.recorded.manifest.cues[id];if(!clip)return false;this.lastCue=this.time;this.recorded.play(clip,{distance,pan});return true;}
 tick(dt,{paused=false,busy=false,pursuit=false,tension=0}={}){if(!Number.isFinite(dt)||dt<0)return;this.paused=paused;if(paused||this.soundtrack?.muted){this.stop();return;}this.time+=Math.min(dt,1);if(busy||pursuit)this.pendingVoice=[];if(!busy&&!pursuit&&!globalThis.speechSynthesis?.speaking&&this.pendingVoice.length){const q=this.pendingVoice.shift();if(this.time-q.at<6)this.voice(q.actorId,q.line,q.meta);}if(!this.ready())return;this.recorded.setAmbience(this.recorded.manifest.ambience);if(this.preferences.music)this.recorded.setMood(pursuit||tension>65?'tense':tension>35?'uneasy':'calm');else this.recorded.setMusic(false);}
 recordingStatus(){const r=this.recorded;if(r.failedClipId)return `Could not load ${r.clip(r.failedClipId)?.title||'a recording'}. Check your connection and reload to try again.`;if(['invalid','unavailable'].includes(r.status))return 'Recorded audio could not load. Check your connection and reload to try again.';if(r.status==='loading')return 'Loading the published soundtrack…';if(r.status==='unloaded')return 'The published soundtrack loads when you enter the street.';const tracks=r.manifest.clips.filter(c=>c.kind==='music'),selected=r.clip(r.musicId||r.lastMusicId);return selected?`${r.musicId?'Playing':'Selected'}: ${selected.title} — ${selected.artist}.` :tracks.length?`Available: ${tracks.map(c=>c.title).join(' · ')}.`:'No recordings are installed.';}
 configure(prefs={}){this.preferences={...this.preferences,...prefs,voice:false,volume:bounded(Number(prefs.volume??this.preferences.volume)||0,0,1)};if(this.bus)this.bus.gain.value=this.preferences.volume;if(!this.preferences.enabled)this.stop();if(!this.preferences.voice&&this.utterance){globalThis.speechSynthesis?.cancel();this.utterance=null;this.pendingVoice=[];}return this.snapshot();}
 voice(actorId,line,meta={}){const {distance=0,pan=0}=meta;if(!this.ready()||distance>14||!line)return false;const clip=this.recorded.voiceId(actorId,line);if(clip){this.recorded.play(clip,{distance,pan,maxDistance:14});return true;}return false;}
 stop(){this.pendingVoice=[];this.recorded.stop();if(this.utterance){globalThis.speechSynthesis?.cancel();this.utterance=null;}}
 snapshot(){return {version:2,...this.preferences};}
 load(s){if(![1,2].includes(s?.version))return false;const {version,...prefs}=s;this.configure({...prefs,music:version===1?true:prefs.music!==false,voice:version===1?false:!!prefs.voice});return true;}
 reset(){this.stop();this.time=0;this.lastCue=-10;}
 dispose(){this.stop();this.recorded.dispose();this.bus?.disconnect();this.bus=null;}
}
